# Hypothesis: a checker should infer covariance for Box[T], which uses T only in a return position, and invariance for Sink[T], which holds T in a mutable list, and should enforce PEP 695 bounds and constraints.
from typing import assert_type, reveal_type


class Box[T]:
    def __init__(self, item: T) -> None:
        self._item = item

    def get(self) -> T:
        return self._item


class Sink[T]:
    def __init__(self) -> None:
        self.items: list[T] = []

    def put(self, item: T) -> None:
        self.items.append(item)


def read_float(b: Box[float]) -> float:
    return b.get()


def fill_float(s: Sink[float]) -> None:
    s.put(2.5)


def fill_int_wrongly(s: Sink[int]) -> None:
    fill_float(s)  # expect-error


def alias_list(xs: list[int]) -> list[float]:
    out: list[float] = xs  # expect-error
    return out


def bounded[N: (int, float)](x: N) -> N:
    return x


def first_or[T: (str, bytes)](xs: list[T], default: T) -> T:
    return xs[0] if xs else default


b = Box(3)
reveal_type(b)
assert_type(read_float(b), float)

s: Sink[float] = Sink()
fill_float(s)
assert s.items == [2.5]
fill_int_wrongly(Sink[int]())

assert_type(bounded(3), int)
assert_type(bounded(2.5), float)
bounded('s')  # expect-error

assert_type(first_or(['a', 'b'], 'c'), str)
first_or([b'x'], 'y')  # expect-error
assert alias_list([1, 2]) == [1, 2]
